<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useStorageText} from './text'
import type {StorageApi} from './api'
import type {Application,Home,ReceiptLine,Product} from './types'
import StoragePhotos from './StoragePhotos.vue'
const props=defineProps<{api:StorageApi;application:Application;home:Home;disabled:boolean}>(),emit=defineEmits<{saved:[];error:[string]}>(),{t}=useStorageText()
const lines=ref<ReceiptLine[]>(props.application.lines.map(l=>({lineId:l.id,productId:l.productId,categoryId:'',nameZh:l.nameZh,nameEn:l.nameEn,quantity:l.quantity,opened:l.opened,source:l.source,ruleId:'',photos:[],note:l.note,location:'',label:''}))),reason=ref(''),query=ref(''),candidates=ref<Product[]>([]),uploading=ref(0),saving=ref(false)
async function search(){try{candidates.value=await props.api.get<Product[]>('/products?query='+encodeURIComponent(query.value))}catch(e){emit('error',String(e))}}
onMounted(()=>{query.value=props.application.lines[0]?.nameZh||props.application.lines[0]?.nameEn||'';void search()})
function choose(line:ReceiptLine,id:string){const p=candidates.value.find(x=>x.id===id);if(p){line.productId=p.id;line.categoryId=p.categoryId;line.nameZh=p.nameZh;line.nameEn=p.nameEn}}
async function submit(){saving.value=true;try{await props.api.command(`/applications/${props.application.id}/receive`,{lines:lines.value,reason:reason.value});emit('saved')}catch(e){emit('error',String(e))}finally{saving.value=false}}
</script>
<template><form class="storage-panel" @submit.prevent="submit"><fieldset :disabled="disabled||saving||uploading>0"><h3>{{t('receive')}}</h3><label>{{t('search')}}<input v-model="query" maxlength="120"></label><button type="button" :disabled="disabled||saving" @click="search">{{t('search')}}</button><article v-for="(l,index) in lines" :key="index" class="storage-panel"><p>{{l.nameZh}} / {{l.nameEn}}</p><button type="button" :disabled="disabled||saving||lines.length>=100" @click="lines.push({...l,quantity:1,opened:true,photos:[],label:''})">{{t('add')}}</button><button v-if="lines.filter(x=>x.lineId===l.lineId).length>1" type="button" @click="lines.splice(index,1)">{{t('remove')}}</button><label>{{t('candidates')}}<select :value="l.productId" @change="choose(l,($event.target as HTMLSelectElement).value)"><option value="">—</option><option v-for="p in candidates" :key="p.id" :value="p.id">{{p.nameZh||p.nameEn}} · {{p.code}}</option></select></label><label><input :checked="!l.productId" type="checkbox" @change="l.productId=null">{{t('newProduct')}}</label><template v-if="!l.productId"><label>{{t('nameZh')}}<input v-model="l.nameZh" maxlength="200"></label><label>{{t('nameEn')}}<input v-model="l.nameEn" maxlength="200"></label><label>{{t('category')}}<select v-model="l.categoryId" required><option value="">—</option><option v-for="c in home.categories" :key="c.id" :value="c.id">{{c.nameZh||c.nameEn}}</option></select></label></template><label>{{t('quantity')}}<input v-model.number="l.quantity" type="number" required min="1" :max="l.opened?1:10000"></label><select v-model="l.opened" @change="l.opened&&(l.quantity=1)"><option :value="false">{{t('whole')}}</option><option :value="true">{{t('opened')}}</option></select><select v-model="l.source"><option value="store">{{t('store')}}</option><option value="customer">{{t('customer')}}</option></select><label>{{t('rules')}}<select v-model="l.ruleId" required><option value="">—</option><option v-for="r in home.rules.filter(r=>!l.categoryId||r.categoryId===l.categoryId)" :key="r.id" :value="r.id">{{r.name}} · {{r.months}} {{t('months')}} · v{{r.version}}</option></select></label><StoragePhotos v-model="l.photos" :api="api" :customer-id="application.customerId" :disabled="disabled||saving" @busy="uploading=Math.max(0,uploading+($event?1:-1))" @error="emit('error',$event)"/><label>{{t('location')}}<input v-model="l.location" maxlength="200"></label><label>{{t('label')}}<input v-model="l.label" maxlength="200"></label><label>{{t('note')}}<textarea v-model="l.note" maxlength="2000"/></label></article><label>{{t('reason')}}<textarea v-model="reason" required maxlength="2000"/></label><button :disabled="disabled||saving||uploading>0||lines.some(l=>!l.photos.length)">{{t('receive')}}</button></fieldset></form></template>
